CREATE TABLE admins(id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) UNIQUE, password VARCHAR(255));
CREATE TABLE players(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(150) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL,
 position VARCHAR(30), shirt_no INT, bio TEXT, photo VARCHAR(255), photo2 VARCHAR(255), photo3 VARCHAR(255),
 nationality VARCHAR(50), dob DATE NULL, height VARCHAR(10), weight VARCHAR(10), foot VARCHAR(10), alt_position VARCHAR(30),
 state_origin VARCHAR(50), state_residence VARCHAR(50), current_club VARCHAR(100), career TEXT, phone VARCHAR(30), contact_email VARCHAR(150),
 certified_on DATE NULL, introduced_by VARCHAR(100), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE news(id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(200) NOT NULL, body TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE hero_images(id INT AUTO_INCREMENT PRIMARY KEY, image VARCHAR(255) NOT NULL, caption VARCHAR(200), sort_order INT DEFAULT 0);
CREATE TABLE gallery(id INT AUTO_INCREMENT PRIMARY KEY, type ENUM('image','video') NOT NULL, file VARCHAR(255) NOT NULL, caption VARCHAR(200), category VARCHAR(50) NOT NULL DEFAULT 'General');
CREATE TABLE matches(id INT AUTO_INCREMENT PRIMARY KEY, opponent VARCHAR(100) NOT NULL, match_date DATE NOT NULL, venue VARCHAR(150),
 home_score INT NULL, away_score INT NULL, played TINYINT DEFAULT 0, opponent_logo VARCHAR(255));
CREATE TABLE goals(id INT AUTO_INCREMENT PRIMARY KEY, player_id INT NOT NULL, match_id INT NULL, qty INT DEFAULT 1,
 FOREIGN KEY(player_id) REFERENCES players(id) ON DELETE CASCADE, FOREIGN KEY(match_id) REFERENCES matches(id) ON DELETE SET NULL);
CREATE TABLE potm(id INT AUTO_INCREMENT PRIMARY KEY, month CHAR(7) UNIQUE NOT NULL, player_id INT NOT NULL, note VARCHAR(300),
 FOREIGN KEY(player_id) REFERENCES players(id) ON DELETE CASCADE);
CREATE TABLE settings(k VARCHAR(50) PRIMARY KEY, v VARCHAR(255));